package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TempRec struct {
	TcSensor string
	TcF      decimal.Decimal
}

var WsEofFlag string = "N"
var WsC decimal.Decimal = decimal.NewFromInt(0)
var WsFreeze int64 = 0
var WsCount int64 = 0
var WsFEd string
var WsCEd string

var tempRec TempRec

var scanner *bufio.Scanner
var inputDone bool
var currentLine string
var hasCurrent bool

func pow10(n int) int64 {
	p := int64(1)
	for i := 0; i < n; i++ {
		p *= 10
	}
	return p
}

func formatZZ9_9(v decimal.Decimal) string {
	abs := v.Abs()
	// scale 1
	scaled := abs.Mul(decimal.NewFromInt(10))
	// scaled should be integral; truncate toward zero
	scaled = scaled.Truncate(0)
	si := scaled.IntPart()
	intPart := si / 10
	fracPart := si % 10
	if fracPart < 0 {
		fracPart = -fracPart
	}
	if intPart < 0 {
		intPart = -intPart
	}
	// drop high-order digits
	intPart = intPart % 1000
	intStr := fmt.Sprintf("%03d", intPart)
	// Z suppression for pattern ZZ9
	// positions 0:Z,1:Z,2:9
	runes := []rune(intStr)
	for i := 0; i < 2; i++ {
		if runes[i] == '0' {
			// check if all remaining to the left are suppressed and this is leading zero
			// Leading zeros are suppressed until first non-zero
			// Find if there is any non-zero before the last 9 that is not suppressed?
			// Simple: if all digits from 0..i are zero and we haven't hit non-zero, suppress
			// Actually need to look ahead: if any non-zero digit exists at position >i
			// then this zero is still leading => suppress
			// If no non-zero ahead, we still suppress Z zeros (leaving last 9 as 0)
			// So if runes[i]=='0', and for all j<=i runes[j]=='0' or suppressed, and there exists
			// a non-zero beyond, it is still leading. Easier to implement classic:
			// scan left to right, suppress Z zeros while all previous are suppressed and
			// the zero is not the mandatory 9 position.
			// For ZZ9, suppress while we haven't seen non-zero.
			// So we can keep a flag seenNonZero.
			_ = runes
			break
		}
	}
	// implement proper Z suppression
	seenNonZero := false
	for i := 0; i < len(runes); i++ {
		isZ := i < 2 // first two are Z
		if runes[i] != '0' {
			seenNonZero = true
		}
		if isZ && !seenNonZero {
			// if this is zero and we haven't seen non-zero, suppress
			// but need to check ahead: if the rest are all zero, we still suppress Z's
			// which matches suppressing leading zeros
			if runes[i] == '0' {
				runes[i] = ' '
			}
		}
		// if seenNonZero, keep as is
	}
	// The above loop marks zeros that are leading. However it will incorrectly keep a zero
	// that is after a non-zero (correct) and suppress zeros before first non-zero.
	// Need to handle case where first non-zero is after some zeros: those zeros should be spaces.
	// The loop does that.
	intFormatted := string(runes)
	fracStr := fmt.Sprintf("%01d", fracPart)
	return intFormatted + "." + fracStr
}

func formatMinusZZ9_99(v decimal.Decimal) string {
	neg := v.IsNegative()
	abs := v.Abs()
	scaled := abs.Mul(decimal.NewFromInt(100))
	scaled = scaled.Truncate(0)
	si := scaled.IntPart()
	intPart := si / 100
	fracPart := si % 100
	if fracPart < 0 {
		fracPart = -fracPart
	}
	if intPart < 0 {
		intPart = -intPart
	}
	intPart = intPart % 1000
	intStr := fmt.Sprintf("%03d", intPart)
	runes := []rune(intStr)
	seenNonZero := false
	for i := 0; i < len(runes); i++ {
		isZ := i < 2
		if runes[i] != '0' {
			seenNonZero = true
		}
		if isZ && !seenNonZero {
			if runes[i] == '0' {
				runes[i] = ' '
			}
		}
	}
	intFormatted := string(runes)
	fracStr := fmt.Sprintf("%02d", fracPart)
	sign := ' '
	if neg {
		sign = '-'
	}
	return string(sign) + intFormatted + "." + fracStr
}

// COBOL paragraphs

func ReadPara() {
	if scanner.Scan() {
		line := scanner.Text()
		// LINE SEQUENTIAL: record is line content; pad on right with spaces if shorter
		if len(line) < 8 {
			line = line + strings.Repeat(" ", 8-len(line))
		} else if len(line) > 8 {
			line = line[:8]
		}
		currentLine = line
		hasCurrent = true
		// parse into TempRec
		sensor := currentLine[0:4]
		fStr := currentLine[4:8]
		// fStr should be digits, maybe spaces? treat spaces as zero
		fStrTrim := strings.TrimSpace(fStr)
		var tcF decimal.Decimal
		if fStrTrim == "" {
			tcF = decimal.NewFromInt(0)
		} else {
			// digits only
			var n int64 = 0
			for _, ch := range fStr {
				if ch >= '0' && ch <= '9' {
					n = n*10 + int64(ch-'0')
				} else if ch == ' ' {
					// pad spaces treated as? keep n*10? But spec says pad with spaces on right for short line,
					// not inside field. So not happen.
					n = n * 10
				}
			}
			tcF = decimal.New(n, -1)
		}
		tempRec.TcSensor = sensor
		tempRec.TcF = tcF
		WsEofFlag = "N"
		inputDone = false
	} else {
		hasCurrent = false
		WsEofFlag = "Y"
		inputDone = true
	}
}

func ProcessPara() {
	// COMPUTE WS-C ROUNDED = (TC-F - 32) * 5 / 9
	diff := tempRec.TcF.Sub(decimal.NewFromInt(32))
	mult := diff.Mul(decimal.NewFromInt(5))
	// divide by 9: multiply before dividing done; use Div
	raw := mult.Div(decimal.NewFromInt(9))
	rounded := raw.Round(2) // half away from zero to scale 2
	// store into WS-C PIC S9(3)V99 : keep low-order digits, scale 2
	// Simulate overflow: keep low-order digits of integer part
	// For S9(3)V99, capacity 3 integer digits, 2 decimal.
	// Dropping high-order digits means integer part modulo 1000.
	// We also need to preserve sign and scale truncation (but scale matches)
	// Implement overflow handling generically:
	// scaled = rounded *100 -> integer
	scaledInt := rounded.Mul(decimal.NewFromInt(100)).Truncate(0).IntPart()
	neg := scaledInt < 0
	absScaled := scaledInt
	if neg {
		absScaled = -absScaled
	}
	intPart := absScaled / 100
	fracPart := absScaled % 100
	intPart = intPart % 1000 // drop high-order
	newAbsScaled := intPart*100 + fracPart
	newScaled := newAbsScaled
	if neg {
		newScaled = -newScaled
	}
	WsC = decimal.New(newScaled, -2)

	if WsC.IsNegative() {
		WsFreeze++
	}
	WsCount++

	WsFEd = formatZZ9_9(tempRec.TcF)
	WsCEd = formatMinusZZ9_99(WsC)

	// DISPLAY TC-SENSOR " " WS-F-ED "F " WS-C-ED "C"
	fmt.Printf("%s %sF %sC\n", tempRec.TcSensor, WsFEd, WsCEd)

	ReadPara()
}

func MainPara() {
	// OPEN INPUT TEMP-FILE and process
	// scanner already opened
	ReadPara()
	for !inputDone {
		ProcessPara()
	}
	// CLOSE TEMP-FILE
	// DISPLAY "READINGS: " WS-COUNT " BELOW ZERO: " WS-FREEZE
	// WS-COUNT and WS-FREEZE are PIC 99 zero-padded to 2 digits
	countStr := fmt.Sprintf("%02d", WsCount)
	freezeStr := fmt.Sprintf("%02d", WsFreeze)
	fmt.Printf("READINGS: %s BELOW ZERO: %s\n", countStr, freezeStr)
}

func main() {
	f, err := os.Open("input.dat")
	if err != nil {
		// if file does not exist, treat as empty
		fmt.Fprintf(os.Stderr, "open input.dat: %v\n", err)
		os.Exit(1)
	}
	defer f.Close()
	scanner = bufio.NewScanner(f)
	// allow long lines; increase buffer if needed
	buf := make([]byte, 0, 64*1024)
	scanner.Buffer(buf, 1024*1024)

	MainPara()
}
